import pathlib
H=pathlib.Path(__file__).parent;R=H.parents[2];p=R/'后续补充检索规则.md';t=p.read_text(encoding='utf8')
(H/'后续补充检索规则_输入留档.md').write_text(t,encoding='utf8')
t=t.replace('申请目的是补充实际可用的科研经费，寻找本人适合承担、合作容易落实、成果负担合理的项目。','申请目的是补充实际可用的科研经费。台账忠实展示具体研究任务、合作要求、经费与成果条款，供本人挑选；不替本人判断是否能够承担。')
t=t.replace('1. 先看当年具体方向和任务，再判断本人是否能负责完成。存在适合承担的明确子方向时，仅保留该子方向，注明应用场景、实验条件及所需伙伴。','1. 依据当年指南具体任务筛选，展示与机器人、人机交互、感知、建模、学习、优化、控制、工业装备及自动化有关的方向，同时保留应用对象、实验条件和合作要求。不得以申请书没有写某项技能推断本人没有该能力。')
t=t.replace('2. 剔除实际任务明显超出上述方向和能力的项目。','2. 剔除实际研究对象及任务与上述研究范围明显无关的项目。')
t=t.replace('3. 材料制备、微电子工艺、化学、生物机制、地学机理、临床牵头研究等，须有本人能够承担的明确算法、机器人或装备任务才可保留。熟悉单位不例外；陌生单位的合适项目应保留。','3. 材料、微电子、化学、生物、地学及临床等行业项目逐项检查实际任务，保留明确相关的建模、感知、算法、测控或装备任务；行业数据、试验和协作要求如实展示。熟悉单位不例外；不根据未提供的个人经历推断资格不符。')
t=t.replace('正式方向不足以判断时标“适合程度待核”。','正式任务资料不足时标“线索待核”，列明缺少的指南或附件。')
t=t.replace('未公开或访问受限的信息明确写待核，留下具体问题及官方联系入口；不推测外拨比例、合作关系或结果。','逐字段区分“官方明确”“官方未公开（已取得公开资料未载）”“资料未取得”“本人情况待确认”；记录具体缺口及官方联系人。已知博士学位直接对应学历条件，年龄、职称、限项与固定合作者不得猜测，不机械追加同一组待核项。')
t=t.replace('排列先后：南京及周边、澳门大学、香港理工大学、华南理工大学及所在区域；其次自动化所及北京区域、西工大及西安区域、重庆大学及重庆区域；其他区域排后。同区域熟悉单位优先，同机构集中，组内当前候选、待核、已截止依次排列。','全表先按状态分组：“可申请”“受理中·条件待核”“截止待确认”“线索待核”“已截止”；资格不符移入剔除记录。各状态组内，南京及周边、澳门大学、香港理工大学、华南理工大学及所在区域优先，其次自动化所及北京区域、西工大及西安区域、重庆大学及重庆区域，其他区域排后。同状态组内同机构集中，兼顾经费条款及截止日期。已截止集中于历史区。其他资助放首页末尾独立区，线索不计为正式课题。')
t+='\n\n核查按执行当天北京时间；截止当天按公告具体时点判断，时点未公开则“截止待确认”。“可申请”须当期正式公告仍在受理、本人已知条件符合且强制合作条件已满足。年度共享公告合并计数并保留全部稳定原编号；不同年度分别保留。下一轮先补查七家核心关系机构的机器人、控制、智能装备及医工平台目录，逐实验室列明已查年份和未查范围，再推进其他地域。\n'
p.write_text(t,encoding='utf8')
